impl Solution{pub fn calculate(s:String)->i32{let mut st=vec![];let(mut n,mut op)=(0,'+');for c in s.chars().chain(std::iter::once('\0')){if c.is_ascii_digit(){n=n*10+c.to_digit(10).unwrap()as i32}if (!c.is_ascii_digit()&&c!=' ')||c=='\0'{match op{'+'=>st.push(n),'-'=>st.push(-n),'*'=>{let x=st.pop().unwrap();st.push(x*n)},'/'=>{let x=st.pop().unwrap();st.push(x/n)},_=>{}}op=c;n=0}}st.iter().sum()}}
